<?php
$page='income';$title='Income';require_once __DIR__.'/includes/functions.php';require_login();$uid=$_SESSION['user_id'];verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';$id=(int)($_POST['id']??0);$desc=trim($_POST['description']??'');$cat=trim($_POST['category']??'');$amount=(float)($_POST['amount']??0);$date=$_POST['transaction_date']??date('Y-m-d');$notes=trim($_POST['notes']??'');if($action==='delete'){$q=$pdo->prepare("DELETE FROM transactions WHERE id=? AND user_id=? AND type='income'");$q->execute([$id,$uid]);set_flash('Income deleted.');}elseif($desc!==''&&$cat!==''&&$amount>0){if($action==='update'){$q=$pdo->prepare("UPDATE transactions SET description=?,category=?,amount=?,transaction_date=?,notes=? WHERE id=? AND user_id=? AND type='income'");$q->execute([$desc,$cat,$amount,$date,$notes,$id,$uid]);set_flash('Income updated.');}else{$q=$pdo->prepare("INSERT INTO transactions(user_id,type,description,category,amount,transaction_date,notes) VALUES(?,'income',?,?,?,?,?)");$q->execute([$uid,$desc,$cat,$amount,$date,$notes]);set_flash('Income added.');}}else set_flash('Enter a description, source, and valid amount.','error');header('Location: income.php');exit;}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM transactions WHERE id=? AND user_id=? AND type='income'");$q->execute([(int)$_GET['edit'],$uid]);$edit=$q->fetch();}$q=$pdo->prepare("SELECT * FROM transactions WHERE user_id=? AND type='income' ORDER BY transaction_date DESC,id DESC");$q->execute([$uid]);$rows=$q->fetchAll();$sources=['Allowance','Salary','Scholarship','Gift','Business','Other'];require 'includes/header.php';?>
<div class="page-head"><div><h1>Income Management</h1><p>Record allowance or other income.</p></div><a class="btn" href="income.php?action=add">＋ Add Income</a></div><?php if(isset($_GET['action'])||$edit):?><div class="card form-card"><h3><?= $edit?'Edit Income':'Add Income' ?></h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="field"><label>Description</label><input name="description" required value="<?=e($edit['description']??'')?>"></div><div class="field"><label>Income Source</label><select name="category"><?php foreach($sources as $s):?><option <?=($edit['category']??'')===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div><div class="field"><label>Amount (₱)</label><input type="number" name="amount" min="0.01" step="0.01" required value="<?=e($edit['amount']??'')?>"></div><div class="field"><label>Date</label><input type="date" name="transaction_date" required value="<?=e($edit['transaction_date']??date('Y-m-d'))?>"></div><div class="field"><label>Notes</label><textarea name="notes"><?=e($edit['notes']??'')?></textarea></div><button class="btn">Save Income</button> <a class="btn secondary" href="income.php">Cancel</a></form></div><?php endif;?><div class="card table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Source</th><th>Amount</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['transaction_date'])?></td><td><?=e($r['description'])?></td><td><?=e($r['category'])?></td><td><?=money($r['amount'])?></td><td><div class="actions"><a class="btn" href="income.php?edit=<?=$r['id']?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger" data-confirm="Delete this income?">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="empty">No income records yet.</p><?php endif;?></div><?php require 'includes/footer.php';?>
